        // A deterministic hash in [0,1), so the coat is a function of its inputs.
        [[nodiscard]] f32 Hash01(u32 a, u32 b)
        {
            u32 h = (a * 0x9E3779B1u) ^ (b * 0x85EBCA77u) ^ 0xC2B2AE3Du;
            h ^= h >> 15;
            h *= 0x2C1B3C6Du;
            h ^= h >> 12;
            h *= 0x297A2D39u;
            h ^= h >> 15;
            return static_cast<f32>(h >> 8) * (1.0f / 16777216.0f);
        }

        // OLO_DOG_DENSITY scales every layer's strand density (look development
        // and the cost sweep); unset is 1.
        [[nodiscard]] f32 DensityScale()
        {
            const char* v = std::getenv("OLO_DOG_DENSITY");
            if (v == nullptr)
            {
                return 1.0f;
            }
            const f32 s = static_cast<f32>(std::atof(v));
            return std::isfinite(s) && s > 0.0f ? s : 1.0f;
        }

        // ---------------------------------------------------------------------
        // The dog's rig description, written by build_dog.py next to the model
        // ---------------------------------------------------------------------
        struct EyeDesc
        {
            std::string Bone;
            glm::vec3 Centre{ 0.0f };
            glm::vec3 Gaze{ 0.0f, 0.0f, 1.0f };
            glm::vec3 Up{ 0.0f, 1.0f, 0.0f };
        };
        struct RigDesc
        {
            f32 EyeRadius = 0.0f;
            f32 SocketRadius = 0.0f;
            std::array<EyeDesc, 2> Eyes; // L, R
            bool Valid = false;
        };

        [[nodiscard]] glm::vec3 Vec3Of(const nlohmann::json& j)
        {
            return { j.at(0).get<f32>(), j.at(1).get<f32>(), j.at(2).get<f32>() };
        }

        [[nodiscard]] RigDesc ReadRig()
        {
            RigDesc rig;
            std::ifstream in(DogDir() / "Dog.rig.json");
            if (!in)
            {
                return rig;
            }
            const nlohmann::json j = nlohmann::json::parse(in, nullptr, false);
            if (j.is_discarded())
            {
                return rig;
            }
            rig.EyeRadius = j.value("eyeRadius", 0.0f);
            rig.SocketRadius = j.value("socketRadius", rig.EyeRadius * 1.15f);
            const char* sides[2] = { "L", "R" };
            for (u32 i = 0; i < 2u; ++i)
            {
                const auto& e = j.at("eyes").at(sides[i]);
                rig.Eyes[i].Bone = e.at("bone").get<std::string>();
                rig.Eyes[i].Centre = Vec3Of(e.at("centre"));
                rig.Eyes[i].Gaze = glm::normalize(Vec3Of(e.at("gaze")));
                rig.Eyes[i].Up = glm::normalize(Vec3Of(e.at("up")));
            }
            rig.Valid = rig.EyeRadius > 0.0f;
            return rig;
        }

        // ---------------------------------------------------------------------
        // Coat regions (the design: see the fixture comment at the top)
        // ---------------------------------------------------------------------
        enum class Region : u8
        {
            Muzzle,
            Face,
            EyeRim, // short fur round the eye opening, combed away from it
            Brow,   // tufts above the eyes: most of a character dog's expression
            Cheek,  // the scruffy fluff below and behind the eyes
            Skull,
            EarOuter,
            EarInner,
            Lid,
            Neck,
            ChestRuff,
            Body,
            Belly,
            Leg,
            LegBack,
            Paw,
            TailTop,
            TailPlume,
            Count
        };

        [[nodiscard]] const char* RegionName(Region r)
        {
            switch (r)
            {
                case Region::Muzzle:
                    return "muzzle";
                case Region::Face:
                    return "face";
                case Region::EyeRim:
                    return "eyerim";
                case Region::Brow:
                    return "brow";
                case Region::Cheek:
                    return "cheek";
                case Region::Skull:
                    return "skull";
                case Region::EarOuter:
                    return "earouter";
                case Region::EarInner:
                    return "earinner";
                case Region::Lid:
                    return "lid";
                case Region::Neck:
                    return "neck";
                case Region::ChestRuff:
                    return "chestruff";
                case Region::Body:
                    return "body";
                case Region::Belly:
                    return "belly";
                case Region::Leg:
                    return "leg";
                case Region::LegBack:
                    return "legback";
                case Region::Paw:
                    return "paw";
                case Region::TailTop:
                    return "tailtop";
                case Region::TailPlume:
                    return "tailplume";
                case Region::Count:
                    break;
            }
            return "body";
        }

